sender, receiver, assets, shares); }``` To withdraw their deployed assets from a BakerFi vault, users must burn a corresponding number of shares to receive a certain amount of assets: ```function _redeemInternal(uint256 shares, address receiver, address holder, bool shouldRedeemETH) private returns(uint256 retAmount) { if(shares == 0) revert InvalidAmount(); if(receiver == address(0) ) revert InvalidReceiver(); if(balanceOf(holder) < shares) revert NotEnoughBalanceToWithdraw(); // Transfer shares to the contract if sender is not the holder if(msg.sender != holder) { if(allowance(holder, msg.sender) < shares) revert NoAllowance(); transferFrom(holder, msg.sender, shares); } // Calculate the amount to withdraw based on shares uint256 withdrawAmount = (shares * totalAssets() ) / totalSupply(); if(withdrawAmount == 0) revert NoAssetsToWithdraw(); @> uint256 amount = _undeploy(withdrawAmount); uint256 fee = 0; uint256 remainingShares = totalSupply() - shares; // Ensure a minimum number of shares are maintained to prevent ratio distortion if(remainingShares < _MINIMUM_SHARE_BALANCE && remainingShares != 0) { revert InvalidShareBalance(); } @> _burn(msg.sender, shares); // Calculate and handle withdrawal fees if(getWithdrawalFee() != 0 && getFeeReceiver() != address(0) ) { fee = amount.mulDivUp(getWithdrawalFee(), PERCENTAGE_PRECISION); if(shouldRedeemETH && _asset() == wETHA() ) { unwrapETH(amount); payable(receiver).sendValue(amount - fee); payable(getFeeReceiver() ).sendValue(fee); } else { IERC20Upgradeable(_asset() ).transfer(receiver, amount - fee); IERC20Upgradeable(_asset() ).transfer(getFeeReceiver(), fee); } } else { if(shouldRedeemETH) { unwrapETH(amount); payable(receiver).sendValue(amount); } else { IERC20Upgradeable(_asset() ).transfer(receiver, amount); } } emit Withdraw(msg.sender, receiver, holder, amount - fee, shares); retAmount = amount - fee; }``` As we can see, the return values of `_deploy()` and `_undeploy()` should represent the amount of asset. In